local lt=tick()
local tv=0.5
local ft=2
task.spawn(function()
    local st=20
    local stt=ft/st
    for i=1,st do
        if s then s.Volume=tv*(i/st) end
        task.wait(stt)
    end
end)
r.RenderStepped:Connect(function()
    if t then
        local nt=tick()
        if nt-lt>=d/1000 then
            lt=nt
            for i=1,tf do
                for y=1,32 do
                    for x=1,32 do
                        local px=pf[i] and pf[i][y] and pf[i][y][x]
                        if px then
                            px.Visible=(i==c)
                        end
                    end
                end
            end
            c=c+1
            if c>tf then c=1 end
            if s then s.TimePosition=(c-1)*(d/1000) end
        end
    end
end)